import{_ as o,l as i,o as e,c as n,v as r,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"定位与指代","description":"","frontmatter":{"title":"定位与指代","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grounding-referring.md","filePath":"llm/grounding-referring.md","lastUpdated":1789023840000}'),c={name:"llm/grounding-referring.md"};function m(f,a,_,u,C,E){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="定位与指代" tabindex="-1">定位与指代 <a class="header-anchor" href="#定位与指代" aria-label="Permalink to &quot;定位与指代&quot;">​</a></h1><div class="epigraph"><p>「左边那只猫」不是分类标签。短语必须落到像素坐标，语言侧的共现才不能顶替格子上的证据。</p><footer>—— Peng 等 Kosmos-2；Chen 等 Shikra；指代基准 RefCOCO / RefCOCO+ / RefCOCOg</footer></div><p><a href="/llm/vlm-hallucination">上一课</a>用 POPE 抓住乱认物体。缺口是绑定：名词、代词、关系短语要对准图上的区域，而不是只答「有」。后课 GUI 默认同一套指代，只是画布换成屏幕控件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/clip">CLIP</a> 对齐的是全局图与整句，不给词–区域。开放 VQA 可以靠主题蒙对。指代理解（REC）要求：给定指代表达，输出框；指代生成（REG）相反。RefCOCO 家族用游戏收集的短语，含位置（左边）、外观、关系；RefCOCO+ 弱化纯位置词，更考外观。</p><p>VLM 要把框写成可生成的 token：量化坐标、特殊位置词、或与文本交错的 <code>&lt;x&gt;&lt;y&gt;</code>。没有这项监督，<a href="/llm/llava-projector">LLaVA 投影器</a> 的 patch 序列只是「可能被注意到的键」，定位是涌现、不保证框准。</p><p><span class="marginnote">坐标协议是产品：归一到 \\([0,1000]\\)、原图像素、还是 patch 下标，训练与推理必须同一套。分辨率一变，未归一的绝对像素会漂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Kosmos-2 把位置写进语言序列，用图文与接地数据联合训。Shikra 在对话里直接输出坐标，强调 referential dialogue。实现上：<a href="/llm/vit-as-encoder">ViT</a> 必须保留空间 patch，不能只投 CLS；2D 位置（<a href="/llm/2d-rope">2D RoPE</a>）让「左/上」可学。评测用 Acc@IoU，并分短短语与长关系句。不要用 POPE 替代 REC。</p>',9)),(e(),s(p,null,{default:t(()=>[h(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E6%8C%87%E4%BB%A3%E8%A1%A8%E8%BE%BE%22%5D%20--%3E%20LLM%5B%22%E5%9B%A0%E6%9E%9C%20LLM%22%5D%0A%20%20PATCH%5B%22%E7%A9%BA%E9%97%B4%20patch%22%5D%20--%3E%20LLM%0A%20%20LLM%20--%3E%20BOX%5B%22%E6%A1%86%E6%88%96%E7%82%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指代成功时，注意力应把短语里的约束（颜色、方位、第几个）打到对应 patch 的键上，再把坐标解码出来。这给物体名词一条必须经过视觉格子的路径，比纯「是否存在」更难用语言先验蒙混——编造的物体没有稳定的框可抄。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自然图框不是点击 UI。下一课把坐标系换成屏幕像素与控件，评测也从 IoU 换成点击命中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定位把短语钉到框/点，堵住只靠共现的物体幻觉。</li><li>必须保留空间 token 与坐标协议。</li><li>RefCOCO 家族测的是指代，不是开放描述。</li><li>出处：Kosmos-2；Shikra；RefCOCO 系列。</li></ul>',6))])}const P=o(c,[["render",m]]);export{A as __pageData,P as default};
